// Presentation and lifecycle controls; never alter a project's internal ID.
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const hash=/^[a-f0-9]{64}$/;
export function projectSelectHTML(catalog,selected='',includeArchived=false,environmentLabel=()=> ''){
  const groups=new Map();
  for(const item of catalog){if(item.lifecycle?.state==='ARCHIVED'&&!includeArchived&&(item.selectionValue??item.project)!==selected)continue;const key=item.logicalProjectId||'';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item);}
  const option=item=>`<option value="${escape(item.selectionValue??item.project)}" title="${escape(item.project)}"${item.machine?` data-project="${escape(item.project)}" data-machine="${escape(item.machine)}"`:''}>${escape(item.displayName||item.project)}${environmentLabel(item.environmentMode)?' · '+escape(environmentLabel(item.environmentMode)):''}${item.machine?' · '+escape(item.machine):''}${item.pending?' · 待确认':''}${item.lifecycle?.state==='ARCHIVED'?' · 已归档':''}</option>`;
  return '<option value="">个人工作区</option>'+[...groups].map(([id,items])=>id?`<optgroup label="${escape(items[0].logicalProjectName||'项目组')}">${items.map(option).join('')}</optgroup>`:items.map(option).join('')).join('');
}
export function createProjectManagement({getContext,call,run,refresh,select}){
  const details=document.createElement('details');details.id='project-management';details.className='execution-panel project-management';
  details.innerHTML='<summary>整理项目</summary><label class="project-archive-filter"><input type="checkbox" data-include-archived>显示归档项目</label><div class="project-management-current"><p data-project-identity class="mono"></p><form data-label-form><label>显示名称<input data-display-name maxlength="80" autocomplete="off"></label><button class="button" type="submit">保存名称</button></form><form data-group-form><label>项目组<select data-group-select><option value="">新建项目组</option></select></label><label>组名称<input data-group-name maxlength="80" autocomplete="off"></label><div class="file-actions"><button class="button" type="submit">保存归组</button><button class="button" type="button" data-group-remove>解除归组</button></div></form><div class="file-actions"><button class="button" type="button" data-project-archive>归档</button><button class="button" type="button" data-retire-plan>检查安全退役</button></div><section data-retire-review hidden><pre data-retire-summary tabindex="0"></pre><button class="button danger" type="button" data-retire-confirm disabled>确认软退役</button></section></div><div class="file-actions"><button class="button quiet" type="button" data-project-catalog>查看跨机项目</button></div><div data-catalog-output></div><div data-retire-recovery hidden><p data-retire-receipt class="mono"></p><button class="button" type="button" data-retire-query>查询原退役请求</button></div><p data-management-status role="status" aria-live="polite"></p><details class="ui-info"><summary aria-label="项目整理说明">ⓘ</summary><div class="ui-info-content">名称和项目组仅用于展示，不移动代码、环境或结果。归档保留历史并暂停新工作；退役仅适用于从未运行且没有活动读写的项目，内容保留在节点私有回收区，不直接删除。</div></details>';
  const q=selector=>details.querySelector(selector),cacheKey=()=>`gpuq-project-retirement-v1:${getContext().owner}`;let contextKey='',plan=null,groups=[],pending=null,labelRevision=null,labelLoaded=false;
  const message=text=>{q('[data-management-status]').textContent=text;};
  const receipt=()=>{try{const value=JSON.parse(localStorage.getItem(cacheKey())||'null');return value?.owner===getContext().owner&&uuid.test(value.key||'')&&hash.test(value.manifestSha256||'')?value:null;}catch{return null;}};
  function recover(){pending=receipt();q('[data-retire-recovery]').hidden=!pending;if(pending)q('[data-retire-receipt]').textContent=`${pending.machine} / ${pending.project} · ${pending.key} · ${pending.state||'结果待核对'}`;}
  function saveReceipt(value){localStorage.setItem(cacheKey(),JSON.stringify(value));pending=value;recover();}
  const same=(token)=>token===getContext().token;
  const ref=()=>{const c=getContext();if(!c.enabled||!c.project||!c.info)throw Error('先选择已确认的项目。');return {machine:c.machine,project:c.project};};
  const action=(button,fn)=>run(button,async()=>{const token=getContext().token;message('正在核对…');try{await fn(token);}catch(error){if(same(token))message(error.message);throw error;}});
  async function reload(token){if(same(token))await refresh();}
  async function catalog(token){const result=await call('projects.catalog',{includeArchived:true});if(!same(token))return;groups=(result.groups||[]).filter(g=>g.logical);const output=q('[data-catalog-output]');output.replaceChildren();for(const group of result.groups||[]){const heading=document.createElement('strong');heading.textContent=group.name;output.append(heading);for(const item of group.instances||[]){const button=document.createElement('button');button.className='button quiet';button.textContent=`${item.machine} · ${item.displayName||item.project}${item.lifecycle?.state==='ARCHIVED'?' · 已归档':''}`;button.addEventListener('click',()=>select(item.machine,item.project));output.append(button);}}message(result.partial?'部分服务器未确认；已显示其余项目。':'项目清单已更新。');renderGroups();}
  function renderGroups(){const current=getContext().info,select=q('[data-group-select]'),old=select.value;select.innerHTML='<option value="">新建项目组</option>'+groups.map(g=>`<option value="${escape(g.id)}">${escape(g.name)}</option>`).join('');if(current?.logicalProjectId&&!groups.some(g=>g.id===current.logicalProjectId)){const option=document.createElement('option');option.value=current.logicalProjectId;option.textContent=current.logicalProjectName;select.append(option);}select.value=old||current?.logicalProjectId||'';}
  details.addEventListener('change',event=>{if(event.target.matches('[data-include-archived]'))refresh({presentationOnly:true});if(event.target.matches('[data-group-select]'))q('[data-group-name]').value=groups.find(g=>g.id===event.target.value)?.name||'';});
  const labelReload=document.createElement('button');labelReload.type='button';labelReload.className='button quiet';labelReload.textContent='读取最新名称';q('[data-label-form]').append(labelReload);
  labelReload.addEventListener('click',()=>action(labelReload,async token=>{const result=await call('projects.label.get',ref());if(!same(token))return;q('[data-display-name]').value=result.displayName;labelRevision=result.revision;labelLoaded=true;message('已读取最新名称；未修改项目。');}));
  q('[data-label-form]').addEventListener('submit',event=>{event.preventDefault();action(event.target.querySelector('button'),async token=>{const reference=ref();if(!Number.isSafeInteger(labelRevision))throw Error('先读取最新名称。');await call('projects.label.set',{...reference,displayName:q('[data-display-name]').value,revision:labelRevision});if(same(token)){labelLoaded=false;message('名称已保存；内部项目 ID 不变。');await reload(token);}});});
  q('[data-group-form]').addEventListener('submit',event=>{event.preventDefault();action(event.target.querySelector('[type=submit]'),async token=>{const c=getContext(),reference=ref(),id=q('[data-group-select]').value||crypto.randomUUID();if(c.info.logicalProjectId&&c.info.logicalProjectId!==id)throw Error('先解除当前归组，再加入其他项目组。');const group=await call('projects.group.get',{id});if(!same(token))return;const members=group.members.some(x=>x.machine===reference.machine&&x.project===reference.project)?group.members:[...group.members,reference];await call('projects.group.set',{id,displayName:q('[data-group-name]').value,revision:group.revision,members,primary:group.primary||reference});if(same(token)){message('归组已保存；各机器的环境和任务仍保持独立。');await reload(token);}});});
  q('[data-group-remove]').addEventListener('click',event=>action(event.target,async token=>{const c=getContext(),reference=ref(),id=c.info.logicalProjectId;if(!id)throw Error('此实例尚未归组。');const group=await call('projects.group.get',{id});if(!same(token))return;const members=group.members.filter(x=>x.machine!==reference.machine||x.project!==reference.project),primary=members.some(x=>x.machine===group.primary?.machine&&x.project===group.primary?.project)?group.primary:members[0]||null;await call('projects.group.set',{id,displayName:group.displayName,revision:group.revision,members,primary});if(same(token)){message('已解除归组，未移动任何文件。');await reload(token);}}));
  q('[data-project-catalog]').addEventListener('click',event=>action(event.target,catalog));
  q('[data-project-archive]').addEventListener('click',event=>{const c=getContext(),archived=c.info?.lifecycle?.state==='ARCHIVED';if(!window.confirm(archived?'恢复此项目的新工作入口？':'归档后停止新工作，历史任务和结果保留。继续？'))return;action(event.target,async token=>{const c=getContext();if(!Number.isSafeInteger(c.info?.lifecycle?.revision))throw Error('节点生命周期功能未确认；没有执行旧接口。');await call(archived?'projects.unarchive':'projects.archive',{...ref(),revision:c.info.lifecycle.revision});if(same(token)){message(archived?'已恢复项目。':'已归档；历史任务和结果保留。');await reload(token);}});});
  q('[data-retire-plan]').addEventListener('click',event=>action(event.target,async token=>{const result=await call('projects.retire.plan',ref());if(!same(token))return;plan={...result,ref:ref(),token};q('[data-retire-review]').hidden=false;q('[data-retire-summary]').textContent=result.state==='ELIGIBLE'?`可软退役 · ${result.entries} 项 · ${result.bytes} B\n内容保留在私有回收区，内部 ID 不再复用。`:`不能退役 · ${(result.blockers||[]).map(x=>x.reason).join('\n')||'状态未确认'}`;q('[data-retire-confirm]').disabled=result.state!=='ELIGIBLE'||!hash.test(result.manifestSha256||'')||!Number.isSafeInteger(result.lifecycle?.revision)||!!pending;}));
  q('[data-retire-confirm]').addEventListener('click',event=>{if(!plan||plan.token!==getContext().token||!window.confirm('确认软退役？仅处理该未使用实例；内容保留，内部 ID 不再复用。'))return;action(event.target,async token=>{const intent={owner:getContext().owner,...plan.ref,key:crypto.randomUUID(),manifestSha256:plan.manifestSha256,revision:plan.lifecycle.revision,state:'结果待核对'};saveReceipt(intent);q('[data-retire-confirm]').disabled=true;try{const result=await call('projects.retire',{machine:intent.machine,project:intent.project,key:intent.key,manifestSha256:intent.manifestSha256,revision:intent.revision});if(!same(token))return;saveReceipt({...intent,state:result.state});plan=null;message(result.state==='RETIRED'?'已软退役；内容保留。':'退役结果未确认；查询原请求，不要新建重试。');if(result.state==='RETIRED')await refresh({retired:intent});}catch(error){throw new Error('退役结果未确认：'+error.message+'。请查询原请求。',{cause:error});}});});
  q('[data-retire-query]').addEventListener('click',event=>action(event.target,async token=>{const intent=receipt();if(!intent)throw Error('没有当前账号的原退役请求。');const result=await call('projects.retire.status',{machine:intent.machine,project:intent.project,key:intent.key});if(!same(token))return;saveReceipt({...intent,state:result.state});message(result.state==='RETIRED'?'已确认软退役；请刷新项目。':'退役结果仍未确认；保留原请求和围栏。');if(result.state==='RETIRED'){localStorage.removeItem(cacheKey());pending=null;recover();}}));
  function update(){const c=getContext(),key=JSON.stringify([c.owner,c.machine,c.project]);if(key!==contextKey){contextKey=key;plan=null;labelLoaded=false;labelRevision=null;q('[data-retire-review]').hidden=true;q('[data-display-name]').value=c.project||'';q('[data-group-name]').value=c.info?.logicalProjectName||'';q('[data-group-select]').value=c.info?.logicalProjectId||'';q('[data-catalog-output]').replaceChildren();groups=[];message('');renderGroups();}if(!labelLoaded&&c.info){q('[data-display-name]').value=c.info.displayName||c.project;labelRevision=c.info.displayNameRevision??0;labelLoaded=true;}recover();q('.project-management-current').hidden=!c.project;q('[data-project-identity]').textContent=c.project?`${c.machine} / ${c.project}`:'';q('[data-project-archive]').textContent=c.info?.lifecycle?.state==='ARCHIVED'?'恢复项目':'归档';for(const control of details.querySelectorAll('button,input,select'))control.disabled=!c.enabled||c.locked;q('[data-retire-confirm]').disabled=!c.enabled||c.locked||!plan||plan.token!==c.token||plan.state!=='ELIGIBLE'||!!pending;q('[data-group-remove]').disabled=!c.info?.logicalProjectId||c.locked;if(c.maintenance)for(const control of details.querySelectorAll('form button[type=submit],[data-project-archive],[data-group-remove],[data-retire-confirm]'))control.disabled=true;}
  return {element:details,update,includeArchived:()=>q('[data-include-archived]').checked};
}
